import{z as s,x as A,o as i,c as p,q as r,j as t,D as e,d as E,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"MLIR 的结构直觉","description":"","frontmatter":{"title":"MLIR 的结构直觉","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cg-mlir-intuition.md","filePath":"cs/cg-mlir-intuition.md","lastUpdated":1791063341000}'),c={name:"cs/cg-mlir-intuition.md"};function B(d,a,I,L,R,m){const o=A("Mermaid");return i(),p("div",null,[a[2]||(a[2]=r('<h1 id="mlir-的结构直觉" tabindex="-1">MLIR 的结构直觉 <a class="header-anchor" href="#mlir-的结构直觉" aria-label="Permalink to &quot;MLIR 的结构直觉&quot;">​</a></h1><div class="epigraph"><p>LLVM IR 是一张写死了词汇的表格；MLIR 把表格本身交给你：词汇、层级、验证，都是可编程的。</p><footer>—— 据 Lattner et al., MLIR, CGO, 2021；MLIR Language Reference 整理</footer></div><p><a href="/cs/cg-jit-deep">上一课</a>把整条优化管线搬进运行时并加上投机；本课回到编译期，问一个结构问题：如果一层 IR 不够用，谁来定义下一层？<a href="/cs/mlir">MLIR 多层 IR</a>给过多方言、逐级 lowering 的画面——LLVM 是终点方言之一，不是唯一 IR。本课补结构直觉：op、region 与重写模式是什么，以及为什么这套东西是<a href="/cs/cg-instruction-selection">指令选择</a>的推广。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LLVM IR 的词汇是封闭集合：指令表写死在参考手册里，面向 C 一级的抽象。往上走一层——张量计算、算子图——词汇对不上；往旁走一步——硬件描述、策略 DSL——语法不合适。硬塞的后果有两种：在外部造一套完整工具链再翻译，解析、优化、验证全套重来；或把高层结构提前打散成 CFG，循环融合这类变换从此看不见对象。缺的是一种 IR 生成框架：让每个领域带自己的词汇进来，逐级、受控地降到机器。</p>',5)),(i(),t(l,null,{default:e(()=>[n(o,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20HIGH%5B%22%E9%A2%86%E5%9F%9F%E7%BB%93%E6%9E%84%EF%BC%9A%E5%BC%A0%E9%87%8F%20%2F%20%E7%AE%97%E5%AD%90%E5%9B%BE%22%5D%20--%3E%7C%22%E7%A1%AC%E5%A1%9E%E8%BF%9B%E5%8D%95%E5%B1%82%20IR%22%7C%20FLAT%5B%22%E6%8F%90%E5%89%8D%E6%89%93%E6%95%A3%E6%88%90%20CFG%22%5D%0A%20%20FLAT%20--%3E%20LOST%5B%22%E5%BE%AA%E7%8E%AF%E8%BE%B9%E7%95%8C%E6%B6%88%E5%A4%B1%EF%BC%9A%E8%9E%8D%E5%90%88%E6%97%A0%E4%BB%8E%E8%B0%88%E8%B5%B7%22%5D%0A%20%20HIGH%20--%3E%7C%22MLIR%EF%BC%9A%E9%80%90%E7%BA%A7%20lowering%22%7C%20KEEP%5B%22%E9%AB%98%E5%B1%82%E6%96%B9%E8%A8%80%E5%85%88%E6%8C%81%E6%9C%89%E7%BB%93%E6%9E%84%22%5D%0A%20%20KEEP%20--%3E%20DROP%5B%22%E6%AF%8F%E4%B8%80%E7%BA%A7%E5%8F%AA%E4%B8%BB%E5%8A%A8%E4%B8%A2%E4%B8%80%E7%BA%A7%E7%BB%93%E6%9E%84%22%5D%0A%20%20DROP%20--%3E%20LOW%5B%22%E6%9C%BA%E5%99%A8%E7%BA%A7%20IR%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">术语翻译：dialect（方言）就是一套自带词汇表与验证规则的 IR 子语言，像 scf 方言专门说「结构化循环」；op 是方言里的最小实体，相当于 LLVM IR 的一条指令——只不过 MLIR 里指令叫什么、长什么样，由方言作者自己定。</span></p><h3 id="结构件-op、region、模式" tabindex="-1">结构件：op、region、模式 <a class="header-anchor" href="#结构件-op、region、模式" aria-label="Permalink to &quot;结构件：op、region、模式&quot;">​</a></h3><p>MLIR 的一切实体是 op：带操作数、结果、属性与 region。region 里装 block，block 构成图——不必是 CFG，<code>scf.for</code> 就把循环的头尾收在一个 op 里。SSA 仍然全局成立，数据流分析的手艺不过期；变化是控制流成了 op 的内容，可以在高层一直保留，直到某个 lowering 主动拆掉。多态靠 trait 与 interface：标了常量类 trait 的 op 自动参与折叠，标了终结符 trait 的 op 定义 region 的出口。翻译的单位是重写模式：「这个 op 在目标方言里等价于这几个 op，代价若干」；驱动器按模式贪心改写到再无合法模式为止。</p><p><span class="marginnote">把这门手艺对着<a href="/cs/cg-instruction-selection">指令选择</a>看：合法化对应 dialect conversion 的类型与操作翻译表，tile 匹配对应 rewrite pattern，代价对应模式的收益。SelectionDAG 是它的特例——词汇固定为机器指令、目标固定为一种。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>lowering 的协议由 conversion 框架定义：声明源方言与目标方言、给出合法性判定、注册模式与类型转换器，框架保证改写过程中 IR 始终可验证。金字塔是工程上的收敛：高层方言（张量、linalg 一类）保持计算意图，中层（scf、vector）承载循环与向量结构，llvm 方言负责对接后端——本课程前六课的世界在那里开始。每一级只丢一级结构：丢了就找不回来，这是多层 IR 的全部纪律。</p><p><span class="marginnote">直觉类比：逐级 lowering 像翻译一篇长难句——先按意群整句直译、保留原文的从句结构，再逐步改成目标语言的习惯语序。一上来就拆成单词硬翻（提前打散成 CFG），原文的修辞和并列结构就再也拼不回去，正如循环边界丢了融合就无从谈起。</span></p>',7)),(i(),t(l,null,{default:e(()=>[n(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E6%96%B9%E8%A8%80%EF%BC%9A%E8%AE%A1%E7%AE%97%E6%84%8F%E5%9B%BE%22%5D%20--%3E%20MID%5B%22%E4%B8%AD%E5%B1%82%EF%BC%9Ascf%20%2F%20vector%22%5D%0A%20%20MID%20--%3E%20LLVM%5B%22llvm%20%E6%96%B9%E8%A8%80%22%5D%0A%20%20LLVM%20--%3E%20IR%5B%22LLVM%20IR%22%5D%0A%20%20IR%20--%3E%20BE%5B%22%E6%8C%87%E4%BB%A4%E9%80%89%E6%8B%A9%E4%B8%8E%E5%90%8E%E7%AB%AF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>验证器是框架的静默功臣：每个方言自带 verifier，非法 IR 在产生的那一刻被拒收，错误就近报告——这把「调试优化器」（下一课的主题）从两个 pass 之间挪到了改写现场。pass 管理器按 region 嵌套递归：pass 可以只作用于一个函数、一个循环、甚至一个 op 的 region，粒度由嵌套结构天然给出；跨层信息靠 analysis 显式请求，而不是全局状态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MLIR 不自带优化：模式要领域作者写，框架只保证改写有序、可验证、可驱动。它也不是「比 LLVM IR 更好的通用 IR」——价值在持有多个 IR 并管理它们之间的翻译；统一到一层，它就退化成另一张写死词汇的表格。源语言的类型系统与语义分析仍在编译器前端，MLIR 不接管，<a href="/cs/mlir">MLIR 多层 IR</a> 已交代过这条边界。</p><p><span class="marginnote">常见误区：初学者容易把 MLIR 当成「LLVM 2.0」——一个更现代的通用中间表示。实际上它恰恰相反：它赌的是「没有任何一层 IR 能同时说所有领域的话」，价值全在多层级并存与受控翻译；把所有方言统一成一层的尝试，等于放弃它存在的理由。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一切皆 op：操作数、结果、属性与 region；SSA 保留，控制流下沉为 op 的内容。</li><li>trait 与 interface 给 op 多态；重写模式加驱动器就是翻译的全部协议。</li><li>合法化、模式、代价：MLIR 的 lowering 是指令选择的推广。</li><li>每级只丢一级结构——多层 IR 的纪律是「丢了就找不回来」。</li><li>出处：Lattner et al., MLIR, CGO 2021；MLIR Language Reference；对照 LLVM IR 参考手册。</li></ul>',7))])}const g=s(c,[["render",B]]);export{_ as __pageData,g as default};
